// NewCreateResponseBody builds the HTTP response body from the result of the
// "create" endpoint of the "featureflag" service.
func NewCreateResponseBody(res *featureflagviews.FeatureflagView) *CreateResponseBody {
	body := &CreateResponseBody{
		ID:                *res.ID,
		TenantID:          *res.TenantID,
		Name:              *res.Name,
		Description:       *res.Description,
		FlagType:          *res.FlagType,
		DefaultValue:      *res.DefaultValue,
		RolloutPercentage: res.RolloutPercentage,
		CreatedAt:         *res.CreatedAt,
		UpdatedAt:         *res.UpdatedAt,
		CreatedBy:         res.CreatedBy,
		UpdatedBy:         res.UpdatedBy,
	}
	if res.TargetAudience != nil {
		body.TargetAudience = make(map[string]any, len(res.TargetAudience))
		for key, val := range res.TargetAudience {
			tk := key
			tv := val
			body.TargetAudience[tk] = tv
		}
	}
	if res.Metadata != nil {
		body.Metadata = make(map[string]any, len(res.Metadata))
		for key, val := range res.Metadata {
			tk := key
			tv := val
			body.Metadata[tk] = tv
		}
	}
	return body
}

