// NewCreateFeatureFlagPayload builds a featureflag service create endpoint
// payload.
func NewCreateFeatureFlagPayload(body *CreateRequestBody) *featureflag.CreateFeatureFlagPayload {
	v := &featureflag.CreateFeatureFlagPayload{
		Name:              *body.Name,
		Description:       *body.Description,
		RolloutPercentage: body.RolloutPercentage,
	}
	if body.FlagType != nil {
		v.FlagType = *body.FlagType
	}
	if body.DefaultValue != nil {
		v.DefaultValue = *body.DefaultValue
	}
	if body.FlagType == nil {
		v.FlagType = "boolean"
	}
	if body.DefaultValue == nil {
		v.DefaultValue = false
	}
	if body.TargetAudience != nil {
		v.TargetAudience = make(map[string]any, len(body.TargetAudience))
		for key, val := range body.TargetAudience {
			tk := key
			tv := val
			v.TargetAudience[tk] = tv
		}
	}
	if body.Metadata != nil {
		v.Metadata = make(map[string]any, len(body.Metadata))
		for key, val := range body.Metadata {
			tk := key
			tv := val
			v.Metadata[tk] = tv
		}
	}

	return v
}

